"""Archive completed workflow evidence without modifying original captures."""
import copy
import hashlib
import json
from pathlib import Path
ROOT = Path('/tmp/codenib-matched-pilot-20261027')
DEST = Path('/home/zhongming/CodeNib-codegraph-benefit/docs/experiments')
def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()
for path in sorted((ROOT / 'matched-runs-v1').glob('*/receipt.json')):
    raw = json.loads(path.read_text())
    if not raw.get('finished_utc'):
        continue
    index = raw['workflow']['workflow_index']
    out = DEST / f'codegraph_matched_workflow_v1_{index:02d}.json'
    if out.exists():
        existing = json.loads(out.read_text())
        assert existing['original_receipt_sha256'] == sha(path)
        continue
    folder = path.parent
    projection = copy.deepcopy(raw)
    # Phase results preserve all terminal data and final answers. Session final
    # usage is kept too; only duplicate answer strings/results are cross-linked.
    for session in projection['sessions']:
        relevant = [p for p in raw['phases'] if p['session'] == session['name'] and p.get('result')]
        session['results'] = [{'phase_result_reference': p['kind']} for p in relevant]
        if session.get('final_result') and relevant:
            session['final_result']['result'] = {'phase_answer_reference': relevant[-1]['kind']}
    observations = {}
    source_captures = {}
    for phase in raw['phases']:
        for key in ('source_before', 'source_after'):
            item = phase.get(key)
            if not item:
                continue
            source = Path(item['path'])
            assert sha(source) == item['sha256']
            source_captures.setdefault(item['sha256'], {'text': source.read_text(), 'original_names': []})['original_names'].append(source.name)
        if not phase.get('trace'):
            continue
        trace = folder / phase['trace']['path']
        assert sha(trace) == phase['trace']['sha256']
        calls, deliveries = {}, []
        init, rates = [], []
        for line in trace.read_text().splitlines():
            row = json.loads(line)
            if row.get('type') == 'AssistantMessage':
                for block in row.get('content', []):
                    if 'name' in block and 'id' in block:
                        if block['id'] in calls:
                            assert calls[block['id']] == block
                        calls[block['id']] = block
            elif row.get('type') == 'UserMessage':
                deliveries.append(row)
            elif row.get('type') == 'SystemMessage':
                init.append(row)
            elif row.get('type') == 'RateLimitEvent':
                rates.append(row)
        observations[phase['kind']] = {'raw_sdk_trace_sha256': sha(trace),
            'raw_sdk_trace_bytes': trace.stat().st_size,
            'init': init, 'rate_events': rates,
            'tool_calls_in_first_observed_order': list(calls.values()),
            'delivered_user_tool_messages_in_order': deliveries}
    value = {'schema_version': 1,
        'scope': 'Completed model execution and delivered tool observations; task acceptance and native repair grading are separate.',
        'original_receipt': str(path), 'original_receipt_sha256': sha(path),
        'receipt_projection': projection,
        'projection_rule': 'All phase results kept. Duplicate session result/answer text is linked to its phase. Assistant intermediate prose and stream usage events remain in the hash-bound original SDK traces; they are not summed as cumulative usage.',
        'source_snapshot_captures_by_sha256': source_captures,
        'phase_observations': observations,
        'repair_patch': (folder / 'repair.patch').read_text() if (folder / 'repair.patch').exists() else None,
        'setup_patch': (folder / 'pre-model.patch').read_text() if (folder / 'pre-model.patch').exists() else None,
        'source_credit': 'No complete ContextBench read score. Delivered shell output remains unattributed until version/file mapping is verified.',
        'archive_implementation_sha256': sha(Path(__file__))}
    data = json.dumps(value, indent=2) + '\n'
    assert len(data.encode()) < 500 * 1024, (out.name, len(data.encode()))
    out.write_text(data)
    print(out.name, out.stat().st_size, sha(out), flush=True)
